import {Component,Input} from '@angular/core';import {CommonModule} from '@angular/common';import {RouterModule} from '@angular/router';import {LanguageService} from '../services/language.service';import {bookingQuery} from './booking-inquiry';import {prebookingText} from './prebooking-text';
@Component({selector:'app-prebooking-summary',standalone:true,imports:[CommonModule,RouterModule],template:`<section class="summary" *ngIf="details as p"><h3>{{t(thread.bookingContext?16:1)}}</h3><dl><div><dt>{{t(2)}}</dt><dd>{{p.startAt|date:'dd/MM/yyyy HH:mm'}}</dd></div><div><dt>{{t(3)}}</dt><dd>{{p.endAt|date:'dd/MM/yyyy HH:mm'}}</dd></div><div *ngIf="p.guests"><dt>{{t(8)}}</dt><dd>{{p.guests}}</dd></div><div *ngIf="p.pickupLocation"><dt>{{t(9)}}</dt><dd>{{p.pickupLocation}}</dd></div><div *ngIf="p.returnLocation"><dt>{{t(10)}}</dt><dd>{{p.returnLocation}}</dd></div><div *ngIf="p.vehiclePlate"><dt>{{t(13)}}</dt><dd>{{p.vehiclePlate}}</dd></div></dl><p *ngIf="p.additionalDriver">✓ {{t(11)}}</p><p *ngIf="p.childSeat">✓ {{t(12)}}</p><p *ngIf="p.rentalAmount">{{p.rentalAmount}} {{p.currency}}</p><p *ngIf="!thread.bookingContext&&thread.prebookingRate?.basePrice">{{t(18)}} : {{thread.prebookingRate.basePrice}} {{thread.prebookingRate.currency}} / {{unitLabel(thread.prebookingRate.pricingUnit)}}</p><p *ngIf="!thread.bookingContext">{{t(5)}}</p><a *ngIf="thread.prebooking&&client&&!thread.linkedBookingId" [routerLink]="['/',thread.type,thread.assetId,'reserver']" [queryParams]="query()">{{t(4)}}</a><a *ngIf="bookingId" [routerLink]="bookingPath()">{{t(7)}}</a></section>`,styles:[`.summary{padding:16px;border:1px solid #bdd7df;background:#f0f7f9;border-radius:12px;margin:12px 0}.summary h3{font-size:18px;margin:0 0 10px}.summary dl{display:flex;gap:14px 24px;flex-wrap:wrap;margin:0}.summary dt{font-size:13px;color:#577480}.summary dd{font-weight:600;margin:4px 0}.summary p{font-size:14px;line-height:1.5}.summary a{display:inline-block;padding:10px 14px;background:#14556a;color:white;border-radius:8px;text-decoration:none}`]})
export class PrebookingSummaryComponent {@Input()thread:any;@Input()uid='';constructor(public language:LanguageService){}t(i:number){return prebookingText(this.language.currentLanguage,i);}get details(){return this.thread?.bookingContext||this.thread?.prebooking;}get client(){return this.thread?.customerId===this.uid;}get bookingId(){return this.thread?.bookingContext?.id||this.thread?.linkedBookingId;}unitLabel(unit:string){const copy:Record<string,string[]>={fr:['heure','jour','nuit'],en:['hour','day','night'],es:['hora','día','noche'],it:['ora','giorno','notte'],de:['Stunde','Tag','Nacht'],nl:['uur','dag','nacht'],ru:['час','день','ночь']};return (copy[this.language.currentLanguage]||copy.en)[unit==='hour'?0:unit==='night'?2:1];}query(){return bookingQuery(this.thread);}bookingPath(){return '/'+this.thread.type+'/'+this.thread.assetId+'/'+(this.client?'bookings/':'admin/reservations/')+this.bookingId;}}
